class Solution:
    def largestPalindrome(self, n: int) -> int:
        if n == 1:
            return 9
        hi = 10 ** n - 1
        lo = hi // 10
        best = 0
        for i in range(hi, lo, -1):
            if i * hi <= best:
                break
            for j in range(i, lo, -1):
                p = i * j
                if p <= best:
                    break
                if str(p) == str(p)[::-1]:
                    best = p
        return best % 1337

