class Solution {
public:
    int largestPalindrome(int n) {
        if (n == 1) return 9;
        long long hi = 1;
        for (int i = 0; i < n; ++i) hi *= 10;
        long long lo = hi / 10;
        hi -= 1;
        long long best = 0;
        for (long long i = hi; i > lo; --i) {
            if (i * hi <= best) break;
            for (long long j = i; j > lo; --j) {
                long long p = i * j;
                if (p <= best) break;
                long long r = 0;
                for (long long t = p; t > 0; t /= 10) r = r * 10 + t % 10;
                if (r == p) best = p;
            }
        }
        return (int)(best % 1337);
    }
};

